55	interface AdapterInstallRequest {
56	  /** npm package name (e.g., "droid-paperclip-adapter") or local path */
57	  packageName: string;
58	  /** True if packageName is a local filesystem path */
59	  isLocalPath?: boolean;
60	  /** Target version for npm packages (optional, defaults to latest) */
61	  version?: string;
62	}
63	
64	interface AdapterCapabilities {
65	  supportsInstructionsBundle: boolean;
66	  supportsSkills: boolean;
67	  supportsLocalAgentJwt: boolean;
68	  requiresMaterializedRuntimeSkills: boolean;
69	}
