71	interface AdapterInfo {
72	  type: string;
73	  label: string;
74	  source: "builtin" | "external";
75	  modelsCount: number;
76	  loaded: boolean;
77	  disabled: boolean;
78	  capabilities: AdapterCapabilities;
79	  /** True when an external plugin has replaced a built-in adapter of the same type. */
80	  overriddenBuiltin?: boolean;
81	  /** True when the external override for a builtin type is currently paused. */
82	  overridePaused?: boolean;
83	  version?: string;
84	  packageName?: string;
85	  isLocalPath?: boolean;
86	}
87	
88	// ---------------------------------------------------------------------------
89	// Helpers
90	// ---------------------------------------------------------------------------
91	
92	/**
93	 * Resolve the adapter package directory (same rules as plugin-loader).
94	 */
95	function resolveAdapterPackageDir(record: AdapterPluginRecord): string {
96	  return record.localPath
97	    ? path.resolve(record.localPath)
98	    : path.resolve(getAdapterPluginsDir(), "node_modules", record.packageName);
99	}
100	
101	/**
102	 * Read `version` from the adapter's package.json on disk.
103	 * This is the source of truth for what is actually installed (npm or local path).
104	 */
105	function readAdapterPackageVersionFromDisk(record: AdapterPluginRecord): string | undefined {
106	  try {
107	    const pkgDir = resolveAdapterPackageDir(record);
108	    const raw = fs.readFileSync(path.join(pkgDir, "package.json"), "utf-8");
109	    const v = JSON.parse(raw).version;
110	    return typeof v === "string" && v.trim().length > 0 ? v.trim() : undefined;
111	  } catch {
112	    return undefined;
113	  }
114	}
115	
116	function buildAdapterCapabilities(adapter: ServerAdapterModule): AdapterCapabilities {
117	  return {
118	    supportsInstructionsBundle: adapter.supportsInstructionsBundle ?? false,
119	    supportsSkills: Boolean(adapter.listSkills || adapter.syncSkills),
120	    supportsLocalAgentJwt: adapter.supportsLocalAgentJwt ?? false,
121	    requiresMaterializedRuntimeSkills: adapter.requiresMaterializedRuntimeSkills ?? false,
122	  };
123	}
